/* @lc app=leetcode id=1802 lang=kotlin */ class Solution { fun side(len: Long, v: Long): Long = if (v - 1 >= len) len * (2 * v - 1 - len) / 2 else (v - 1) * v / 2 + (len - (v - 1)) fun maxValue(n: Int, index: Int, maxSum: Int): Int = generateSequence(1 to maxSum) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (mid + side(index.toLong(), mid.toLong()) + side((n - 1 - index).toLong(), mid.toLong()) <= maxSum) mid to hi else lo to mid - 1 } }.last().first }